import Box from "@mui/material/Box";
import {  Button, Typography, Grid } from "@mui/material";
import ImageIcon from "@mui/icons-material/Image";
import React from "react";
import { FileUpload } from "../../interfaces/interfaces";

type SetAvatarProps = {
  handleCoverFile: (event: React.ChangeEvent<HTMLInputElement>) => void;
  coverFile?: FileUpload;
  onSubmit: () => void;
};

const SetAvatarView: React.FC<SetAvatarProps> = ({
  onSubmit,
  handleCoverFile,
  coverFile
}) => {
  return (
    <Box padding="30px">
        <Grid item sm={12} md={6}>
          <Box paddingBottom="20px">
            <input
              color="primary"
              accept="image/*"
              type="file"
              
              onChange={handleCoverFile}
              id="icon-button-file"
              style={{ display: "none" }}
            />
            <label htmlFor="icon-button-file">
              <Button
                variant="contained"
                component="span"
                size="large"
                color="primary"
              >
                 <ImageIcon /> 
               <Typography fontFamily="Termina">Set Brand Avatar</Typography>
             
              </Button>
            </label>
          </Box>

          {
            coverFile ? <ImageFile file={coverFile.file!} /> : <Box />
          }
        </Grid>

        <Grid item sm={12} paddingTop="15px">
          <Button variant="contained" onClick={onSubmit}>
            <Typography fontFamily="Termina">Submit</Typography>
   
          </Button>
        </Grid>
    </Box>
  );
};

type ImageFileType = {
  file: File;
};

function ImageFile(props: ImageFileType) {
  const [src, setSrc] = React.useState<string>();
  const reader = new FileReader();
  reader.onloadend = function (e) {
    setSrc(reader.result! as string);
  };

  return (
    <Box width="100%" display="flex" alignItems={"center"} paddingBottom="5px">
      <Box width="100px" height="100px">
        <img
          src={src}
          alt="upload"
          style={{ width: "100px", height: "100px", objectFit: "cover" }}
        />
      </Box>
      <Typography paddingLeft="10px">{props.file.name}</Typography>
    </Box>
  );
}

export default SetAvatarView;
