import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import { Button, Card, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle, Divider, ListItem, ListItemIcon, ListItemText, TextField } from '@mui/material';
import { DashboardDrawer } from './DashboardDrawer';
// import Nav from '../../components/Nav';
import AddShoppingCartIcon from '@mui/icons-material/AddShoppingCart';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import IconButton from '@mui/material/IconButton';
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { SellerI } from '../../interfaces/interfaces';
import Api from '../../Api';
import { Tooltip } from '@material-ui/core';

export function AdminBrandsPage() {
  const navigate = useNavigate();

  const [open, setOpen] = React.useState(false);
  const [open2, setOpen2] = React.useState(false);
  const [brands, setBrands] = React.useState<SellerI[]>([]);
  const [brand, setBrand] = React.useState<SellerI>();
  const [update, setUpdate] = React.useState(0);

  React.useEffect(() => {
    async function fetch() {
      try {
        const _brands: SellerI[] = await Api.brands.getBrands();
        setBrands(_brands);
      }
      catch (error) {
        console.log(error);
      }
    }
    fetch();
  }, [update]);


  const handleClickOpen = () => { setOpen(true); };
  const handleClose = () => { setOpen(false); setUpdate(update + 1); };
  const handleClose2 = () => { setOpen2(false); setUpdate(update + 1); };

  return (

    <Box
      width="100vw" height="100vh"
      bgcolor={"#F7F8FC"}
      display="flex" flexDirection="row"
    >
      {/* New Brand Dialog */}
      <NewBrandDialog open={open} handleClose={handleClose} />
      <DeleteBrandDialog open={open2} handleClose={handleClose2} brand={brand} />

      {/* <Nav /> */}
      <DashboardDrawer selected='Brands' />
      <Box flexGrow={1} display="flex" flexDirection={"column"} padding="30px">

        {/* Title */}
        <Typography fontWeight={500} fontSize={24} paddingBottom="15px" fontFamily="Termina">Brands</Typography>
        <Box flexGrow={1} paddingTop="15px">
          <Card style={{ width: "100%", height: "100%" }} elevation={0} variant="outlined">
            {/* Add New Brand Button */}
            <Box padding="30px">
              <Button
                // fullWidth 
                variant="contained"
                style={{ backgroundColor: "#DD042B", textTransform: "none", height: "42px", boxShadow: "0px 4px 12px 0px #DD042B3D" }}
                onClick={handleClickOpen}>
                <Typography color="white" fontFamily="Termina" fontSize={14}>
                  Add New Brand
                </Typography>
              </Button>
            </Box>

            <Divider />
            {brands.map((brand) => {
              return (
                <ListItem divider={true} key={brand._id}>
                  <ListItemText>
                    <img src={brand.avatar} height="30px"></img>
                    &nbsp;&nbsp;&nbsp;
                    <b>{brand.shopName}</b>
                    {/* <Divider /> */}
                    
                  </ListItemText>


                  <ListItemIcon>
                    <Tooltip title="View Brand Clothing Items">
                      <IconButton onClick={() => navigate(`/admin/brands/${brand._id}`)}>
                        <AddShoppingCartIcon />
                      </IconButton>
                    </Tooltip>

                    <Tooltip title="Delete Brand">
                      <IconButton onClick={() => { setBrand(brand); setOpen2(true); }}>
                        <DeleteIcon />
                      </IconButton>
                    </Tooltip>
                  </ListItemIcon>
                </ListItem>
              );
            })}
          </Card>
        </Box>
      </Box>
    </Box>
  );
}

const NewSeller: { [key: string]: string } = {
  shopName: "",
  email: "",
}

const NewBrandDialog: React.FC<{ open: boolean, handleClose: VoidFunction }> = ({ open, handleClose }) => {
  const [data, setData] = React.useState(NewSeller);

  const onChanged = (ev: React.ChangeEvent<HTMLInputElement>): void => {
    const _data = { ...data };
    _data[ev.target.name] = ev.target.value;
    setData(_data);
  }

  const onCreate = async () => {
    handleClose();
    try {
      const seller: SellerI = await Api.brands.create({ shopName: data.shopName, email: data.email } as SellerI);
      console.log("created seller: ", seller);
    }
    catch (error) {
      console.log(error);
    }
  };


  return (
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle>Add new brand</DialogTitle>
      <DialogContent>
        {/* <DialogContentText>
          To subscribe to this website, please enter your email address here. We
          will send updates occasionally.
        </DialogContentText> */}
        <TextField
          autoFocus
          margin="dense"
          label="Brand Name"
          type="text"
          fullWidth
          variant="standard"

          name="shopName"
          onChange={onChanged}
        />

        <TextField
          margin="dense"
          id="name"
          label="Email Address"
          type="email"
          fullWidth
          variant="standard"

          name="email"
          onChange={onChanged}
        />

      </DialogContent>
      <DialogActions>
        <Button color="error" onClick={handleClose}>Cancel</Button>
        <Button onClick={onCreate}>Create</Button>
      </DialogActions>
    </Dialog>
  );
}


const DeleteBrandDialog: React.FC<{ open: boolean, handleClose: VoidFunction, brand: SellerI | undefined }> = ({ open, handleClose, brand }) => {


  const onDelete = async () => {

    try {
      await Api.brands.delete(brand?._id ?? "");
      console.log("deleted seller id: ", brand?._id);
    }
    catch (error) {
      console.log(error);
    }
    handleClose();
  };


  return (
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle>Delete</DialogTitle>
      <DialogContent>
        <DialogContentText>
          are you sure you want to delete the brand {brand?.shopName} ?
        </DialogContentText>
      </DialogContent>

      <DialogActions>
        <Button onClick={handleClose}>Keep Brand</Button>
        <Button color="error" onClick={onDelete}>Delete!!</Button>
      </DialogActions>
    </Dialog>
  );
}
