const NewItem: { [key: string]: string } = {
  name: "",
  seller: "",
  description: "",
  tags: "",
  sizesInStock: "",
  price: "",

  gender: "Unisex",
  clothingType: "Tops",
  purchaseUrl: "",
};

const NewClothingDialog: React.FC<{
  open: boolean;
  handleClose: VoidFunction;
  id?: string;
}> = ({ open, handleClose, id }) => {
  const [data, setData] = React.useState(NewItem);
  const [file, setFile] = React.useState<FileUpload | null>(null);
  const [files, setFiles] = React.useState<FileUpload[]>([]);

  const onChanged = (ev: React.ChangeEvent<HTMLInputElement>): void => {
    const _data = { ...data };
    _data[ev.target.name] = ev.target.value;
    setData(_data);
    console.log(_data);
  };

  const handleChange = (ev: SelectChangeEvent): void => {
    const _data = { ...data };
    _data[ev.target.name] = ev.target.value;
    setData(_data);

    console.log(_data);
  };

  const onCreate = async () => {
    handleClose();
    try {
      const item: ClothingItemI = await Api.items.create({
        seller: id,
        name: data.name,
        description: data.description,
        sizesInStock: data.sizesInStock,
        price: data.price,

        clothingType: data.clothingType,
        gender: data.gender,
        purchaseUrl: data.purchaseUrl,
      } as ClothingItemI);

      if (file) {
        console.log("adding photo");
        await Api.items.addPhoto(item._id ?? "", file);
      }

      console.log("created item: ", item);
    } catch (error) {
      console.log(error);
    }
  };

  const handleFileRead = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const filesList: FileList | null = event.target.files;
    if (!filesList?.length) return;

    const base64 = await convertBase64(filesList[0]);
    const fileName: string = filesList[0].name;

    console.log(base64);
    console.log(fileName);

    setFile({ base64, fileName });

    const _files: FileUpload[] = [];
    for (let i = 0; i < filesList.length; i++) {
      const _file = filesList[i];
      const _base64 = await convertBase64(_file);
      const _fileName: string = _file.name;
      _files.push({
        fileName: _fileName,
        base64: _base64,
      });
    }
  };

  const convertBase64 = (file: File) => {
    return new Promise((resolve, reject) => {
      const fileReader = new FileReader();
      fileReader.readAsDataURL(file);
      fileReader.onload = () => {
        resolve(fileReader.result);
      };
      fileReader.onerror = (error) => {
        reject(error);
      };
    });
  };

  return (
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle>Add new clothing Item</DialogTitle>
      <DialogContent>
        {/* <DialogContentText>
          To subscribe to this website, please enter your email address here. We
          will send updates occasionally.
        </DialogContentText> */}
        <TextField
          autoFocus
          margin="dense"
          label="Item Name"
          type="text"
          fullWidth
          variant="standard"
          name="name"
          onChange={onChanged}
        />

        {/* <TextField
          display="none"
          margin="dense"
          label="description"
          type="text"
          fullWidth
          variant="standard"
          multiline
          rows={3}
          name="description"
          onChange={onChanged}
        /> */}

        <Box paddingTop="10px">
          <Select
            value={data.gender}
            label="Gender"
            name="gender"
            onChange={handleChange}
            margin="dense"
            size="small"
            fullWidth
          >
            <MenuItem value={"Men"}>Men</MenuItem>
            <MenuItem value={"Women"}>Women</MenuItem>
            <MenuItem value={"Unisex"}>Unisex</MenuItem>
          </Select>
        </Box>

        <Box paddingTop="10px">
          <Select
            value={data.clothingType}
            label="Clothing Type"
            name="clothingType"
            onChange={handleChange}
            size="small"
            fullWidth
          >
            {ClothingTypes.map((clothingItem) => (
              <MenuItem key={clothingItem} value={clothingItem}>
                {clothingItem}
              </MenuItem>
            ))}
          </Select>
        </Box>

        <TextField
          margin="dense"
          label="Sizes i.e: xs, sm, md, lg, xl, xxl"
          type="text"
          fullWidth
          variant="standard"
          name="sizesInStock"
          onChange={onChanged}
        />

        <TextField
          margin="dense"
          label="Purchase URL"
          type="text"
          fullWidth
          variant="standard"
          name="purchaseUrl"
          onChange={onChanged}
        />

        <TextField
          margin="dense"
          id="name"
          label="Price"
          type="text"
          fullWidth
          variant="standard"
          name="price"
          onChange={onChanged}
        />

        <TextField
          type="file"
          inputProps={{ accept: "image/*" }}
          required
          label="Image"
          name="originalFileName"
          onChange={handleFileRead}
          size="small"
          variant="standard"
        />
      </DialogContent>
      <DialogActions>
        <Button color="error" onClick={handleClose}>
          Cancel
        </Button>
        <Button onClick={onCreate}>Create</Button>
      </DialogActions>
    </Dialog>
  );
};
