import React from "react";
import {
  FileUpload,
  SellerI,
} from "../../interfaces/interfaces";
import Api from "../../Api";
import SetAvatarView from "./SetAvatarView";
import { useParams } from "react-router-dom";



type ControllerProps = {
  sellerId: string;
};

export default function SetAvatar() {
  const { id } = useParams();
  return <SetAvatarController sellerId={id ?? ""} />;
}

function SetAvatarController(props: ControllerProps) {
  const { sellerId } = props;
  const [coverFile, setCoverFile] = React.useState<FileUpload>();

  const onSubmit = async () => {
    try {
      if (coverFile) {
        // TODO: set Avatar
        console.log("setting avatar");
        const a = await Api.brands.setAvatar(sellerId ?? "", coverFile);
        console.log(a);
      }
    } catch (error) {
      console.log(error);
    }
  };

  const handleCoverFile = async (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const filesList: FileList | null = event.target.files;
    if (!filesList?.length) return;

    const base64 = await convertBase64(filesList[0]);
    const fileName: string = filesList[0].name;

    console.log(base64);
    console.log(fileName);

    setCoverFile({ base64, fileName, file: filesList[0] });
  };

  const convertBase64 = (file: File) => {
    return new Promise((resolve, reject) => {
      const fileReader = new FileReader();
      fileReader.readAsDataURL(file);
      fileReader.onload = () => {
        resolve(fileReader.result);
      };
      fileReader.onerror = (error) => {
        reject(error);
      };
    });
  };

  return (
    <SetAvatarView
      coverFile={coverFile}
      handleCoverFile={handleCoverFile}
      onSubmit={onSubmit}
    />
  );
}
