import React from "react";
import {
  ClothingItemI,
  FileUpload,
  SellerI,
} from "../../interfaces/interfaces";
import Api from "../../Api";
import { ListItemAvatar } from "@material-ui/core";
import Select, { SelectChangeEvent } from "@mui/material/Select";
import { useNavigate, useParams } from "react-router-dom";
import NewItemView from "./NewItemView";

const ClothingTypes = [
  "Tops",
  "Hoodies",
  "Sweatshirts",
  "Long-Sleeves",
  "Pants",
  "Jeans",
  "Sweatpants",
  "Shorts",
  "Skirts",
  "Jackets",
  "Dresses",
  "Necklaces",
  "Socks",
  "Hats",
  "Croptops"
];

const NewItem: { [key: string]: string } = {
  seller: "",
  name: "",
  price: "",
  purchaseUrl: "",
  description: "",
  gender: "Unisex",
  clothingType: "Tops",
  tags: "",
  sizesInStock: "",
  sizes: "",
  promoCode: "",
  saleIsFinal: "false",
  dontGoToRevery: "false",
};

type ControllerProps = {
  sellerId: string;
};

export default function NewItemPage() {
  const { id } = useParams();
  return <NewItemController sellerId={id ?? ""} />;
}

function NewItemController(props: ControllerProps) {
  const { sellerId } = props;
  const [data, setData] = React.useState(NewItem);
  const [files, setFiles] = React.useState<FileUpload[]>([]);
  const [coverFile, setCoverFile] = React.useState<FileUpload>();
  const navigate = useNavigate();

  const onDataChanged = (ev: React.ChangeEvent<HTMLInputElement>): void => {
    const _data = { ...data };
    _data[ev.target.name] = ev.target.value;
    setData(_data);
    console.log(_data);
  };

  const onSelectChange = (ev: SelectChangeEvent): void => {
    const _data = { ...data };
    _data[ev.target.name] = ev.target.value;
    setData(_data);

    console.log(_data);
  };

  const onSubmit = async () => {
    try {
      const item: ClothingItemI = await Api.items.create({
        seller: sellerId,
        name: data.name,
        description: data.description,
        sizesInStock: data.sizesInStock,
        sizes: data.sizes,

        overlayURLs: data.overlayURLs,
        torsoOverlayURLs: data.torsoOverlayURLs,
        saleAmount: data.saleAmount,
        dontGoToRevery: data.dontGoToRevery,
        itemsPageIndex: data.itemsPageIndex,
        reviews: data.reviews,
        shippingCost: data.shippingCost,
        videoURL: data.videoURL,
        price: data.price,

        clothingType: data.clothingType,
        gender: data.gender,
        purchaseUrl: data.purchaseUrl,

        promoCode: data.promoCode,
        saleIsFinal: data.saleIsFinal,
        tags: data.tags,
      } as ClothingItemI);

      if (coverFile) {
        await Api.items.addPhoto(item._id ?? "", coverFile);
      }

      if (files.length > 0) {
        for (const file of files) {
          console.log("adding photo");
          await Api.items.addPhoto(item._id ?? "", file);
        }
      }

      console.log("created item: ", item);
      navigate("/admin/brands/" + sellerId);
    } catch (error) {
      console.log(error);
    }
  };

  const handleCoverFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const filesList: FileList | null = event.target.files;
    if (!filesList?.length) return;

    const base64 = await convertBase64(filesList[0]);
    const fileName: string = filesList[0].name;

    console.log(base64);
    console.log(fileName);

    setCoverFile({ base64, fileName, file: filesList[0] });
  };

  const handleFileRead = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const filesList: FileList | null = event.target.files;
    if (!filesList?.length) return;

    const _files: FileUpload[] = [];
    for (let i = 0; i < filesList.length; i++) {
      const _file = filesList[i];
      const _base64 = await convertBase64(_file);
      const _fileName: string = _file.name;
      console.log(_fileName);

      _files.push({
        fileName: _fileName,
        base64: _base64,
        file: _file,
      });
    }
    setFiles(_files);
  };

  const convertBase64 = (file: File) => {
    return new Promise((resolve, reject) => {
      const fileReader = new FileReader();
      fileReader.readAsDataURL(file);
      fileReader.onload = () => {
        resolve(fileReader.result);
      };
      fileReader.onerror = (error) => {
        reject(error);
      };
    });
  };

  function back() {
    navigate("/admin/brands/" + sellerId);
  }

  return (
    <NewItemView
      data={data}
      clothingTypes={ClothingTypes}
      files={files}
      coverFile={coverFile}
      setFiles={setFiles}
      back={back}
      onDataChanged={onDataChanged}
      handleFileRead={handleFileRead}
      handleCoverFile={handleCoverFile}
      onSelectChanged={onSelectChange}
      onSubmit={onSubmit}
    />
  );
}
