import React from "react";
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import { Container, Grid, TextField } from '@mui/material';
import { Button } from '@material-ui/core';
import { useNavigate } from 'react-router-dom';
// import Nav from '../components/Nav';
import UploadIcon from '@mui/icons-material/Upload';

const Data: { [key: string]: string } = {
  name: "",
  companyName: "",
  website: "",
  email: "",
  shippingPolicy: "",
}

function PartnerWithUsPage() {
  const [, setError] = React.useState("");
  const [, setLoading] = React.useState(true);

  const [data, setData] = React.useState(Data);


  const navigate = useNavigate();

  React.useEffect(() => {
    setLoading(false);
  }, [])

  function onDataChanged(ev: React.ChangeEvent<HTMLInputElement>): void {
    const name: string = ev.target.name;
    const _data = { ...data };
    _data[name] = ev.target.value;
    setData(_data);
  }

  const onSubmit = async () => {
    // TODO: call login api
    try {
      // setError("");
      // const user = await Api.auth.login(email, password);
      // setUser(user);
      // localStorage.setItem("user", JSON.stringify(user));
      // await login(email, password);
      navigate('/brands/submitted');
    }
    catch (err: any) {
      try {
        const message: string | undefined = err.response.data;
        console.log(message);
        if (message)
          setError(message);
        else
          setError("error loging in");
      } catch (error) { }
    }
  }

  return (
    <Box
      width="100vw" minHeight="100vh"
      bgcolor={"#FFFFFF"}
      display="flex" flexDirection="column"
    // alignContent="center" 
    // justifyContent="center" 
    // alignItems={"center"} 
    // textAlign={"center"}
    >

      <Box width="100%" bgcolor="#000000" height="160px" display="flex" flexDirection="column" textAlign="center" justifyContent="center" >
        <Typography fontFamily={"Termina"} fontSize={40} fontWeight={500} color="white">
          Partner with us
        </Typography>
      </Box>

      <Container>


        <Grid container spacing={1} paddingTop="60px">
          <Grid item xs={12} md={6}>
            <Box padding="10px">
              <TextField onChange={onDataChanged} label="Name" variant="filled" size='small' style={{ borderRadius: 4 }} InputProps={{ disableUnderline: true, }} fullWidth={true} />
            </Box>
          </Grid>

          <Grid item xs={12} md={6}>
            <Box padding="10px">
              <TextField onChange={onDataChanged} label="Company Name" variant="filled" size='small' style={{ borderRadius: 4 }} InputProps={{ disableUnderline: true, }} fullWidth={true} />
            </Box>
          </Grid>

          <Grid item xs={12}>
            <Box padding="10px">
              <TextField onChange={onDataChanged} label="Website Url" variant="filled" size='small' style={{ borderRadius: 4 }} InputProps={{ disableUnderline: true, }} fullWidth={true} />
            </Box>
          </Grid>

          <Grid item xs={12} md={6}>
            <Box padding="10px">
              <TextField onChange={onDataChanged} label="Email" variant="filled" size='small' style={{ borderRadius: 4 }} InputProps={{ disableUnderline: true, }} fullWidth={true} />
            </Box>
          </Grid>

          <Grid item xs={12}>
            <Grid item xs={12} md={6}>
              <Box padding="10px">
                <Typography paddingBottom={"10px"}>Which E-commerce platform do you have your website on?</Typography>
                <TextField onChange={onDataChanged} label="E-commerce platform" variant="filled" size='small' style={{ borderRadius: 4 }} InputProps={{ disableUnderline: true, }} fullWidth={true} />
              </Box>
            </Grid>
          </Grid>

          <Grid item xs={6}>
            <Box padding="10px">
              <Typography paddingBottom={"10px"}>Describe your shipping policy</Typography>
              <TextField onChange={onDataChanged} label="Shipping Policy" rows={4} multiline={true} variant="filled" size='small' style={{ borderRadius: 4 }} InputProps={{ disableUnderline: true, }} fullWidth={true} />
            </Box>
          </Grid>

          <Grid item xs={12}>
            <Grid item xs={12} md={6}>
              <Box padding="10px">
                <Typography paddingBottom={"10px"}>Attach your clothing catalogue (CSV file)</Typography>
                <Box width="100%" height="200px" bgcolor={"rgba(0, 0, 0, 0.06)"} borderRadius="5px" display="flex" alignItems={"center"} justifyContent={"center"}>
                  <Typography fontSize={18} fontWeight={600} textAlign={"center"}> <UploadIcon /> Upload or Drag Your File</Typography>
                </Box>
              </Box>
            </Grid>
          </Grid>

          <Grid item xs={12} md={3}>
            <Box padding="10px">
              <Button fullWidth variant="contained" style={{ backgroundColor: "#DD042B", textTransform: "none", height: "42px", boxShadow: "0px 4px 12px 0px #DD042B3D" }} onClick={onSubmit}>
                <Typography color="white" fontSize={14}>
                  Submit
                </Typography>
              </Button>
            </Box>
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
}

export default PartnerWithUsPage;