import React from 'react';
import './App.css';
import { Route, Routes } from 'react-router-dom';
import HomePage from './pages/HomePage';
import BrandsPage from './pages/BrandsPage';
import StylistsPage from './pages/StylistsPage';
import LoginPage from './admin/LoginPage';
import SubmittedPage from './brands/SubmittedPage';
import PartnerWithUsPage from './brands/PartnerWithUsPage';
import { AdminBrandsPage } from './admin/dashboard/AdminBrandsPage';
import { useLocation } from 'react-router-dom';
import ReactGA from "react-ga4";
import { EditBrandsPage } from './admin/dashboard/EditBrandPage';
import NewItemPage from './admin/dashboard/NewItemController';
import EditItemPage from './admin/dashboard/EditItemController';
import { AdminStatsPage } from './admin/dashboard/AdminStatsPage';

// const UA = "UA-217661993-1";
const MEASUREMENT_ID = "G-44DV5KNM1E";

try {
  ReactGA.initialize(MEASUREMENT_ID, { testMode: false });
  console.log("initilized GA: G-300104300");
}
catch (error) {
  console.log("Failed to initilized GA");
  console.log(error);
}

function App() {
  let location = useLocation();
  React.useEffect(() => {
    console.log("path: " + location.pathname);
    ReactGA.send({ hitType: "pageview", page: location.pathname });
  }, [location]);

  return (
    <Routes>
      <Route path="/brands" element={<BrandsPage />} />
      <Route path="/stylists" element={<StylistsPage />} />

      <Route path="/brands/partner-with-us" element={<PartnerWithUsPage />} />
      <Route path="/brands/submitted" element={<SubmittedPage />} />

      <Route path="/admin/login" element={<LoginPage />} />
      <Route path="/admin/brands" element={<AdminBrandsPage />} />
      <Route path="/admin/brands/:id" element={<EditBrandsPage />} />
      <Route path="/admin/brands/:id/new-item" element={<NewItemPage />} />
      <Route path="/admin/edit-item/:id" element={<EditItemPage />} />
      <Route path="/admin/stats" element={<AdminStatsPage />} />
      <Route path="/admin/*" element={<AdminBrandsPage />} />
      <Route path="/*" element={<HomePage />} />
    </Routes>
  );
}

export default App;
